const storageKey="hasVisitedBlog",welcomeMessage=document.getElementById("first-visit-message");function checkFirstVisit(){null===localStorage.getItem(storageKey)&&(welcomeMessage&&(welcomeMessage.style.display="block"),localStorage.setItem(storageKey,"true"))}function closeWelcomeMessage(){welcomeMessage&&(welcomeMessage.style.display="none")}document.addEventListener("DOMContentLoaded",checkFirstVisit);